from pathlib import Path
import base64,shutil,datetime
p=Path('/opt/kiwoom/dashboard-source/dist/index.html');s=p.read_text()
assert 'account-holdings-currency-module' not in s
assert '</body>' in s
suffix='.before-holdings-currency-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S')
shutil.copy2(p,str(p)+suffix)
s=s.replace('</body>',base64.b64decode('').decode()+'\n</body>');p.write_text(s)
print('HOLDINGS_CURRENCY_DEPLOYED',suffix)
